-- ====================================================================
-- stfd_features：STFD v2.1 九大模組臨床特徵字典（86項Feature）
-- 適用資料庫：sleep_tcm_db（或你自己命名的資料庫）
-- 使用方式：在 Supabase Dashboard → SQL Editor → 貼上全部內容 → Run
-- ====================================================================

CREATE TABLE stfd_features (
  feature_id VARCHAR(10) PRIMARY KEY,
  module_code VARCHAR(2) NOT NULL,
  priority VARCHAR(20) NOT NULL,
  feature_type VARCHAR(60) NULL,
  name_en VARCHAR(150) NULL,
  name_zh_tw VARCHAR(60) NOT NULL,
  clinical_definition VARCHAR(300) NULL,
  clinical_boundary VARCHAR(300) NULL,
  patient_question_zh_tw VARCHAR(300) NOT NULL,
  response_type VARCHAR(200) NULL,
  time_window VARCHAR(30) NULL,
  related_features VARCHAR(100) NULL,
  sleep_relevance VARCHAR(150) NULL,
  tcm_knowledge_link VARCHAR(300) NULL,
  evidence_status VARCHAR(30) NOT NULL DEFAULT 'Draft',
  version_added VARCHAR(10) NOT NULL DEFAULT '2.1',
  status VARCHAR(20) NOT NULL DEFAULT 'active'
);


