-- 欄位說明
COMMENT ON COLUMN stfd_features.feature_id IS '如 S01、M01、F01';
COMMENT ON COLUMN stfd_features.module_code IS 'A-I';
COMMENT ON COLUMN stfd_features.priority IS 'Core/Extended/Conditional';
COMMENT ON COLUMN stfd_features.feature_type IS '如 Sleep symptom';
COMMENT ON COLUMN stfd_features.name_en IS '英文概念名稱';
COMMENT ON COLUMN stfd_features.name_zh_tw IS '中文概念名稱';
COMMENT ON COLUMN stfd_features.clinical_definition IS '臨床定義';
COMMENT ON COLUMN stfd_features.clinical_boundary IS '邊界／與相近概念的區分';
COMMENT ON COLUMN stfd_features.patient_question_zh_tw IS '病人友善問句';
COMMENT ON COLUMN stfd_features.response_type IS '建議回答格式';
COMMENT ON COLUMN stfd_features.time_window IS '回顧時間窗';
COMMENT ON COLUMN stfd_features.related_features IS '關聯Feature ID清單';
COMMENT ON COLUMN stfd_features.sleep_relevance IS '睡眠相關標籤';
COMMENT ON COLUMN stfd_features.tcm_knowledge_link IS '中醫知識節點描述';
